--preconditions onFail:MARK_RAN
--precondition-sql-check expectedResult:0 SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'requests' AND table_name = 'request_attachments';
CREATE TABLE "requests"."request_attachments"
(
    "attachment_id"   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "request_id"      bigint       NOT NULL,
    "file_url"        varchar(255) NOT NULL,
    "attachment_type" varchar(255) NOT NULL,
    "uploaded_at"     timestamp DEFAULT (CURRENT_TIMESTAMP)
);


COMMENT
ON TABLE "requests"."request_attachments" IS 'This table will hold the URLs of the attachments of the requests';
COMMENT
ON COLUMN "requests"."request_attachments"."request_id" IS 'Allows multiple attachments per request';
COMMENT
ON COLUMN "requests"."request_attachments"."file_url" IS 'S3/Cloud storage path';
COMMENT
ON COLUMN "requests"."request_attachments"."attachment_type" IS '.mp4, .jpg , etc';


CREATE INDEX ON "requests"."request_attachments" ("request_id");